verification_commands.ac1:
set -u
# ac1 - F1 (decoded view finds the 11 hidden legs) + F2 (plaintext view intact) + F4 (the
# auditor itself never goes red). Read-only against the repository: the pre-t105 index is
# taken from a base index BLOB derived at run time from the branch shape (HEAD^ first, then
# merge-base with main, then merge-base with origin/main; every candidate, its rejection
# reason and the acceptance is printed - never a main-tip-at-groom literal, the t102 lesson
# WAL 1221/1222) and written into a throwaway dir, so the auditor is exercised against the
# pre-repremised shape WITHOUT touching the tracked index.
# WHY A FIXTURE AT ALL: on the post-t105 tree the hidden class is NOT empty but the eleven
# live anchors have moved to docs/issues/closed/, so a run against the tracked index alone
# cannot demonstrate that the decoded view found the ORIGINAL live pins. The pre-t105 blob
# is the only shape that carries them.
# WHY --index IS ENOUGH: the shipped auditor already takes --index and resolves pinned paths
# against the CURRENT WORKING DIRECTORY (the repository root), not against the index's own
# directory, so pointing it at a copy in a throwaway dir keeps classification honest while
# the tracked index stays untouched.
test -f docs/tools/leg_path_pin_audit.py || { echo "ac1 RED: docs/tools/leg_path_pin_audit.py is missing - run this fence from the repository root"; exit 1; }
command -v python3 >/dev/null 2>&1 || { echo "ac1 RED: python3 is missing - this fence's validator is python3 by contract, with no skip path"; exit 1; }
TMP=$(mktemp -d) || { echo "ac1 RED: mktemp -d failed"; exit 1; }
export TMP
trap 'rm -rf "$TMP"' EXIT INT TERM
python3 - <<'PYAC1' || exit 1
import base64, json, os, re, subprocess, sys
IDX = "docs/state/merge_test_index.json"
TOOL = "docs/tools/leg_path_pin_audit.py"
TMP = os.environ["TMP"]
HIDDEN = {282: ("t76", "ac4"), 306: ("t86", "ac1"), 307: ("t86", "ac2"),
          308: ("t86", "ac3"), 309: ("t86", "ac4"), 310: ("t87", "ac1"),
          311: ("t87", "ac2"), 312: ("t87", "ac3"), 315: ("t88", "ac1"),
          316: ("t88", "ac2"), 317: ("t88", "ac3")}
PLAIN = {230: ("t62", "ac6"), 279: ("t78", "ac4")}
KEYS = ("GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_OBJECT_DIRECTORY",
        "GIT_COMMON_DIR", "GIT_PREFIX")
def fail(m):
    sys.stderr.write("ac1 RED: " + m + "\n"); raise SystemExit(1)
def cr(b):
    return b.replace(b"\r\n", b"\n")
def env():
    return {k: v for k, v in os.environ.items() if k not in KEYS}
def git(args):
    p = subprocess.run(["git"] + args, capture_output=True, env=env())
    return cr(p.stdout or b""), (p.stderr or b"").decode("utf-8", "replace"), p.returncode
def rev(spec):
    out, _, _ = git(["rev-parse", "--revs-only", spec])
    return out.decode("utf-8", "replace").strip()
def merge_base(ref):
    if not rev(ref):
        return ""
    out, _, _ = git(["merge-base", ref, "HEAD"])
    return out.decode("utf-8", "replace").strip()
def blob(rev_, path):
    out, err, _ = git(["show", "%s:%s" % (rev_, path)])
    if not out:
        w = subprocess.run(["wslpath", "-w", os.getcwd()], capture_output=True,
                           text=True, env=env()).stdout.strip().replace("\r\n", "\n")
        out, err, _ = git(["cmd.exe", "/d", "/c", "git -C %s show %s:%s" % (w, rev_, path)])
    if not out:
        fail("blob %s:%s unreadable through WSL git AND cmd.exe git (%s)" % (rev_, path, err[:120]))
    return out
def blob_at(rev_, path):
    probe, _, rc = git(["rev-parse", "--verify", "-q", "%s:%s" % (rev_, path)])
    if rc != 0 or not probe.strip():
        return None
    return blob(rev_, path)
def rejection(cand):
    if not cand:
        return "unresolvable on this checkout"
    if cand == rev("HEAD"):
        return "is HEAD itself, not a base"
    _, _, rc = git(["merge-base", "--is-ancestor", cand, "HEAD"])
    if rc != 0:
        return "is not an ancestor of HEAD"
    at = blob_at(cand, IDX)
    if at is None:
        return "%s does not exist there" % IDX
    # The acceptance test for THIS fence is semantic, not "differs from the working
    # tree": the blob must still CARRY the hidden live anchors. On a t106-only branch
    # the index is untouched by the product, so "differs from the worktree" would
    # wrongly reject the branch parent; on a t105 branch it is the re-premise itself
    # that makes a blob unusable as a pre-t105 fixture, and the anchor scan below is
    # exactly that measurement (it is re-run on the chosen blob before use).
    return ""
CANDS = [("HEAD^ (the branch parent)", rev("HEAD^")),
         ("merge-base(main, HEAD)", merge_base("main")),
         ("merge-base(origin/main, HEAD)", merge_base("origin/main"))]
BASE = LABEL = ""
for label, cand in CANDS:
    if BASE:
        continue
    why = rejection(cand)
    if why:
        print("ac1 evidence: base candidate %s -> %s rejected: %s" % (label, cand[:7] or "(none)", why))
    else:
        BASE, LABEL = cand, label
        print("ac1 evidence: base candidate %s -> %s ACCEPTED" % (label, cand[:7]))
if not BASE:
    fail("no candidate base is a strict pre-product ancestor of HEAD - either t105's re-premise is not on this branch (both cards land together), or the branch shape is not (base -> product); name the shape and re-groom rather than pin a literal")
base_raw = blob_at(BASE, IDX)
base_idx = json.loads(base_raw.decode("utf-8"))
# The fixture must actually carry the live anchors, or this fence would be proving nothing.
CHUNK = re.compile(r"(?<![A-Za-z0-9+/=])([A-Za-z0-9+/]{80,}={0,2})(?![A-Za-z0-9+/=])")
LIVE_PIN = re.compile(r"(?<!closed/)docs/issues/t\d+\.md")
seen = {}
for i, leg in enumerate(base_idx["tests"]):
    hits = set(LIVE_PIN.findall(leg.get("command") or ""))
    for m in CHUNK.finditer(leg.get("command") or ""):
        try:
            hits.update(LIVE_PIN.findall(base64.b64decode(m.group(1)).decode("utf-8")))
        except Exception:
            pass
    if hits:
        seen[i] = sorted(hits)
if set(seen) != set(HIDDEN) | set(PLAIN):
    fail("the fixture index at %s carries live pins on legs %s, expected the 13 legs 230/279/282/306-312/315-317 - this fence's premise is that the BASE index still carries the pre-re-premise live anchors (t105 owns the re-premise); if the branch has no such base, the card must be re-groomed against the shape that exists" % (BASE[:7], sorted(seen)))
fixture = os.path.join(TMP, "index_pret105.json")
with open(fixture, "wb") as fh:
    fh.write(base_raw)
print("ac1 evidence: fixture %s (%d bytes, %d legs) written from the base blob at %s - it carries live pins on exactly the 13 expected legs" % (os.path.basename(fixture), len(base_raw), len(base_idx["tests"]), BASE[:7]))
p = subprocess.run(["python3", TOOL, "--index", fixture], capture_output=True, text=True)
out = (p.stdout or "").replace("\r\n", "\n")
sys.stdout.write("".join("  | " + ln + "\n" for ln in out.split("\n")[:26] if ln))
if p.returncode != 0:
    fail("F4 VIOLATION: the auditor exited %d on a parseable index (stderr: %s) - the shipped contract is that an AUDIT reports by printing and exits 0 whenever the index loads; only --expect-pins may return 1 and it was not passed here, so the auditor has become the thing that goes red" % (p.returncode, (p.stderr or "").strip()[:160]))
print("ac1 evidence: F4 holds - exit 0 on a parseable pre-t105 index that carries 13 pinned legs, 11 of them invisible to the shipped plaintext-only auditor")
if "leg_path_pin_audit: legs_scanned=%d" % len(base_idx["tests"]) not in out:
    fail("legs_scanned is not %d - the auditor must scan every leg of the fixture it was given" % len(base_idx["tests"]))
def pin_lines(leg_idx):
    return [ln for ln in out.split("\n")
            if re.match(r"^leg_path_pin_audit: pin leg %s " % leg_idx, ln)]
PIN_RE_CLASS = re.compile(r"^leg_path_pin_audit: pin leg (\d+) issue=(\S+) ac=(\S+) path=(\S+) status=(\S+) via=(\S+)$")
for i, (issue_id, ac) in sorted(HIDDEN.items()):
    lines = pin_lines(i)
    if not lines:
        fail("F1 VIOLATION: the pre-t105 fixture hides a live card path in leg %d (%s %s) - measured at groom by decoding its base64 payload - but the auditor printed no pin line for it. The shipped auditor saw only legs 230 and 279 (pinned_legs=2, the t104 record); a decode view that still misses leg %d is not the upgrade this card exists for" % (i, issue_id, ac, i))
    if not any("via=decoded_base64" in ln for ln in lines):
        fail("leg %d (%s %s) is reported but no line carries via=decoded_base64 - the auditor must DISCLOSE how each pin was found (plaintext / decoded_base64 / plaintext+decoded_base64), otherwise a reader cannot tell the new class from the old one and the 11-leg finding is not attributable" % (i, issue_id, ac))
    if not any(("issue=%s" % issue_id) in ln for ln in lines):
        fail("leg %d's pin lines do not carry issue=%s - leg numbering must never be bare (WAL 1240 W2)" % (i, issue_id))
for i, (issue_id, ac) in sorted(PLAIN.items()):
    lines = pin_lines(i)
    if not lines:
        fail("F2 VIOLATION: leg %d (%s %s) is a PLAINTEXT pin in the shipped t104 record and is now absent from the auditor's output - the upgrade must ADD a view, not replace one" % (i, issue_id, ac))
    if not any("via=plaintext" in ln for ln in lines):
        fail("leg %d (%s %s) is reported but not with via=plaintext - its pin is in the command text itself, and mislabelling it makes the plaintext/decoded split (and the findings record built from it) wrong" % (i, issue_id, ac))
m = re.search(r"^leg_path_pin_audit: pinned_legs=(\d+)$", out, re.M)
if not m:
    fail("no summary line 'leg_path_pin_audit: pinned_legs=<N>' (exact format) - the summary contract is unchanged from the shipped auditor and ac4 cross-checks it")
if int(m.group(1)) != 13:
    fail("pinned_legs=%s on the pre-t105 fixture, expected 13 (the 2 plaintext legs of the t104 record PLUS the 11 hidden legs of the WAL 1236 class) - a count of 2 means the decode view is absent, anything else means the scan is not the specified one" % m.group(1))
mb = re.search(r"^leg_path_pin_audit: broken_pins=(\d+)$", out, re.M)
if not mb or int(mb.group(1)) != 0:
    fail("broken_pins on the pre-t105 fixture is %s, expected 0 - the auditor's broken class is missing_everywhere (the card exists in NO location), and on this tree every archived card still resolves under docs/issues/closed/, so the correct report is status=moved with broken_pins=0. The three legs that are RED at baseline (282/308/309, measured in t105's card) go RED through their OWN guards on the live path, which is a different mechanism from this classification; the missing_everywhere class is proven separately by ac3's planted pin, which exists nowhere" % (mb.group(1) if mb else "(no line)"))
not_moved = []
for i in sorted(HIDDEN):
    sts = [PIN_RE_CLASS.match(ln).group(4) for ln in out.split("\n")
           if PIN_RE_CLASS.match(ln) and PIN_RE_CLASS.match(ln).group(1) == str(i)]
    if not sts:
        fail("leg %d produced no classifiable pin line" % i)
    if all(s == "present" for s in sts):
        not_moved.append(i)
if not_moved:
    fail("legs %s report EVERY pinned path as present on the pre-t105 fixture - but their cards were archived to docs/issues/closed/, so at least the live docs/issues/tXX.md path must classify moved. A checker that calls an archived pin 'present' is reporting the archival break as healthy, which is the exact blindness WAL 1236 records" % not_moved)
print("ac1 evidence: broken_pins=0 (archived cards resolve under closed/, so the class is 'moved' not 'missing_everywhere' - ac3 proves the missing class by planting a pin that exists nowhere), and all 11 hidden legs carry at least one non-present classification: the archival break is VISIBLE")
print("ac1 GREEN: DECODED VIEW PRESENT AND ATTRIBUTED - against the pre-t105 index at %s the auditor reports all 11 hidden legs with via=decoded_base64, keeps both plaintext legs with via=plaintext, derives pinned_legs=13 with broken_pins=0 and the archival break reported as status=moved, and still exits 0 (F1+F2+F4)" % BASE[:7])
PYAC1

verification_commands.ac2:
set -u
# ac2 - THE BYTE-STABILITY CONTRACT, MEASURED NOT ASSERTED. Read-only.
# "Byte-stable" is defined against the t104 FINDINGS RECORD (docs/state/outputs/
# t104_hygiene_findings.json), not against raw stdout, because the upgrade deliberately
# ADDS two fields (ac= and via=) to each pin line; requiring identical stdout would forbid
# the very disclosure ac1 demands. What must not move is the OBSERVATION: for every leg the
# shipped auditor pinned, the (leg, path, status) triple must be identical.
# This fence therefore runs BOTH auditors - the shipped one taken from the run-time-derived
# base index blob (so it is the t104 tool, not whatever is in the worktree) and the upgraded
# one in the worktree - against the SAME index, and diffs the triples. Then it re-checks
# those triples against the byte-frozen t104 record's own fields, and finally proves the t104
# record is still byte-identical to its base blob (t104 custody: this card may not rewrite
# the record it is measured against).
test -f docs/tools/leg_path_pin_audit.py || { echo "ac2 RED: the auditor is missing - run this fence from the repository root"; exit 1; }
test -f docs/state/outputs/t104_hygiene_findings.json || { echo "ac2 RED: docs/state/outputs/t104_hygiene_findings.json missing - it is the reference this card is measured against"; exit 1; }
command -v python3 >/dev/null 2>&1 || { echo "ac2 RED: python3 is missing"; exit 1; }
TMP=$(mktemp -d) || { echo "ac2 RED: mktemp -d failed"; exit 1; }
export TMP
trap 'rm -rf "$TMP"' EXIT INT TERM
python3 - <<'PYAC2' || exit 1
import json, os, re, subprocess, sys
IDX = "docs/state/merge_test_index.json"
TOOL = "docs/tools/leg_path_pin_audit.py"
REC104 = "docs/state/outputs/t104_hygiene_findings.json"
TMP = os.environ["TMP"]
KEYS = ("GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_OBJECT_DIRECTORY",
        "GIT_COMMON_DIR", "GIT_PREFIX")
def fail(m):
    sys.stderr.write("ac2 RED: " + m + "\n"); raise SystemExit(1)
def cr(b):
    return b.replace(b"\r\n", b"\n")
def env():
    return {k: v for k, v in os.environ.items() if k not in KEYS}
def git(args):
    p = subprocess.run(["git"] + args, capture_output=True, env=env())
    return cr(p.stdout or b""), (p.stderr or b"").decode("utf-8", "replace"), p.returncode
def rev(spec):
    out, _, _ = git(["rev-parse", "--revs-only", spec])
    return out.decode("utf-8", "replace").strip()
def merge_base(ref):
    if not rev(ref):
        return ""
    out, _, _ = git(["merge-base", ref, "HEAD"])
    return out.decode("utf-8", "replace").strip()
def blob(rev_, path):
    out, err, _ = git(["show", "%s:%s" % (rev_, path)])
    if not out:
        w = subprocess.run(["wslpath", "-w", os.getcwd()], capture_output=True,
                           text=True, env=env()).stdout.strip().replace("\r\n", "\n")
        out, err, _ = git(["cmd.exe", "/d", "/c", "git -C %s show %s:%s" % (w, rev_, path)])
    if not out:
        fail("blob %s:%s unreadable through WSL git AND cmd.exe git (%s)" % (rev_, path, err[:120]))
    return out
def blob_at(rev_, path):
    probe, _, rc = git(["rev-parse", "--verify", "-q", "%s:%s" % (rev_, path)])
    if rc != 0 or not probe.strip():
        return None
    return blob(rev_, path)
def rejection(cand):
    if not cand:
        return "unresolvable on this checkout"
    if cand == rev("HEAD"):
        return "is HEAD itself, not a base"
    _, _, rc = git(["merge-base", "--is-ancestor", cand, "HEAD"])
    if rc != 0:
        return "is not an ancestor of HEAD"
    at = blob_at(cand, TOOL)
    if at is None:
        return "%s does not exist there" % TOOL
    try:
        w = cr(open(TOOL, "rb").read())
    except OSError:
        return "%s is missing from this tree" % TOOL
    if at == w:
        return "%s already equals its blob there - that commit carries THIS card's upgrade, so the shipped comparator would be the upgraded tool and the diff would be vacuous" % TOOL
    return ""
CANDS = [("HEAD^ (the branch parent)", rev("HEAD^")),
         ("merge-base(main, HEAD)", merge_base("main")),
         ("merge-base(origin/main, HEAD)", merge_base("origin/main"))]
BASE = LABEL = ""
for label, cand in CANDS:
    if BASE:
        continue
    why = rejection(cand)
    if why:
        print("ac2 evidence: base candidate %s -> %s rejected: %s" % (label, cand[:7] or "(none)", why))
    else:
        BASE, LABEL = cand, label
        print("ac2 evidence: base candidate %s -> %s ACCEPTED" % (label, cand[:7]))
if not BASE:
    fail("no candidate base is a strict pre-upgrade ancestor of HEAD - the shipped-vs-upgrade comparison has nothing to compare against; name the branch shape and re-groom rather than pin a literal")
shipped = cr(blob_at(BASE, TOOL))
if open(TOOL, "rb").read().replace(b"\r\n", b"\n") == shipped:
    fail("the worktree auditor is byte-identical to its %s blob - the upgrade has not been applied; this fence measures a change, and comparing a tool against itself proves nothing" % BASE[:7])
old_tool = os.path.join(TMP, "leg_path_pin_audit_shipped.py")
with open(old_tool, "wb") as fh:
    fh.write(shipped)
print("ac2 evidence: shipped (pre-upgrade) auditor restored from %s:%s (%d bytes) into a throwaway dir; the worktree auditor is %d bytes and differs" % (BASE[:7], TOOL, len(shipped), len(cr(open(TOOL, "rb").read()))))
PIN_RE_OLD = re.compile(r"^leg_path_pin_audit: pin leg (\d+) issue=(\S+) path=(\S+) status=(\S+)$")
PIN_RE_NEW = re.compile(r"^leg_path_pin_audit: pin leg (\d+) issue=(\S+) ac=(\S+) path=(\S+) status=(\S+) via=(\S+)$")
def triples(tool, index, rx, pi, si):
    p = subprocess.run(["python3", tool, "--index", index], capture_output=True, text=True)
    out = (p.stdout or "").replace("\r\n", "\n")
    got = set()
    for ln in out.split("\n"):
        m = rx.match(ln)
        if m:
            got.add((int(m.group(1)), m.group(pi), m.group(si)))
    if not got:
        fail("%s printed no parseable pin lines against %s (rc=%d) - the line contract is the interface both auditors share (the shipped one ends at status=, the upgraded one adds ac= and via=), and dropping it silently would hide a regression from this fence" % (os.path.basename(tool), index, p.returncode))
    return got, out
old_tr, old_out = triples(old_tool, IDX, PIN_RE_OLD, 3, 4)
new_tr, new_out = triples(TOOL, IDX, PIN_RE_NEW, 4, 5)
lost = old_tr - new_tr
if lost:
    fail("F2 VIOLATION - the upgrade LOST observations the shipped auditor made: %s. The upgrade ADDS a decoded view; every (leg, path, status) triple the t104 tool derived must still be derived, or a pin silently stops being reported and the archival break recurs unseen" % sorted(lost))
gained_plaintext_legs = sorted({i for (i, p_, s_) in new_tr} - {i for (i, p_, s_) in old_tr})
print("ac2 evidence: shipped auditor derived %d triples over legs %s; the upgrade derives %d triples over legs %s (the %d extra legs are the decoded class)" % (len(old_tr), sorted({i for i, _, _ in old_tr}), len(new_tr), sorted({i for i, _, _ in new_tr}), len(gained_plaintext_legs)))
rec104_raw = open(REC104, "rb").read()
rec104 = json.loads(rec104_raw.decode("utf-8"))
pp = rec104.get("path_pin_findings")
if not isinstance(pp, list):
    fail("%s carries no path_pin_findings list - the t104 record is the reference for byte-stability and it must be readable" % REC104)
rec_triples = set()
for e in pp:
    for pth in e.get("literal_paths", []):
        rec_triples.add((int(e["leg_index"]), pth, e["classification"]))
# The record is LEG-level: one classification per leg (the worst status among its pinned
# paths), while the auditor prints one line per PATH. Comparing them field-for-field
# therefore has to be done at the same granularity, or a leg that pins two paths with two
# different statuses (leg 230: docs/issues/groom/t62.md resolves, docs/issues/t62.md is
# archived) can never match its own record entry - measured at groom, where a naive triple
# comparison REDd on the CORRECT product.
worst = {}
for (i, path, status) in new_tr:
    rank = {"present": 0, "moved": 1, "missing_everywhere": 2}[status]
    worst[i] = max(worst.get(i, -1), rank)
rank2 = {0: "present", 1: "moved", 2: "missing_everywhere"}
bad_cls = []
for e in pp:
    i = int(e["leg_index"])
    want = e["classification"]
    got = rank2.get(worst.get(i, -1), "(leg not reported)")
    if got != want:
        bad_cls.append((i, want, got))
if bad_cls:
    fail("the t104 record's leg-level classification is not reproduced: %s (record -> fresh run). The record says leg 230's t62 pins are 'moved' (the live path is archived, the groom/ mirror resolves) and leg 279's t78 pin is 'present' (the named exemption is live); if the upgrade disagrees with the t104 record, it disagrees with the measurement this card was opened from" % bad_cls)
paths_rec = {(int(e["leg_index"]), p) for e in pp for p in e.get("literal_paths", [])}
paths_new = {(i, p) for (i, p, _) in new_tr}
if not paths_rec <= paths_new:
    fail("the t104 record pins %s which the upgraded auditor no longer reports (%s) - the upgrade ADDS a decoded view, so every plaintext observation of t104 must survive" % (sorted(paths_rec - paths_new), sorted(paths_new)[:6]))
print("ac2 evidence: the t104 record's %d leg entries (legs %s) reproduce: literal_paths survive and each leg's worst-status classification matches" % (len(pp), sorted(int(e["leg_index"]) for e in pp)))
for e in pp:
    idx_i = int(e["leg_index"])
    lines = [ln for ln in new_out.split("\n") if PIN_RE_NEW.match(ln) and PIN_RE_NEW.match(ln).group(1) == str(idx_i)]
    for ln in lines:
        if "via=plaintext" not in ln:
            fail("leg %d is a PLAINTEXT pin per the t104 record but the upgraded line reads '%s' - it must carry via=plaintext" % (idx_i, ln))
    if not any(("ac=%s" % e.get("ac")) in ln for ln in lines):
        fail("leg %d's upgraded lines do not carry ac=%s - the t104 record already stores ac per finding (leg 230 is t62/ac6, leg 279 is t78/ac4, measured from the record itself), and WAL 1240 W2 requires leg numbering to travel with issue_id AND ac" % (idx_i, e.get("ac")))
print("ac2 evidence: the t104 record's legs %s also carry via=plaintext and ac= on every upgraded pin line" % sorted(int(e["leg_index"]) for e in pp))
b104 = blob_at(BASE, REC104)
if b104 is None:
    fail("%s does not exist at the derived base %s - it cannot be proven byte-frozen against a base that lacks it" % (REC104, BASE[:7]))
if b104 != rec104_raw.replace(b"\r\n", b"\n"):
    fail("%s is NOT byte-identical to its %s blob - t104 owns that record; this card's findings live in docs/state/outputs/t106_checker_b64_findings.json and the reference record must stay byte-frozen so the stability contract stays checkable by later cards" % (REC104, BASE[:7]))
print("ac2 evidence: %s is byte-identical to its %s blob (%d bytes) - the reference record is untouched" % (REC104, BASE[:7], len(b104)))
print("ac2 GREEN: PLAINTEXT DETECTION BYTE-STABLE - every (leg, path, status) triple the shipped t104 auditor derived is still derived by the upgrade, the t104 record's legs 230/279 findings reproduce field-for-field with via=plaintext and ac=, and the t104 record itself is byte-frozen")
PYAC2

